const items = $input.all();
const now = new Date();
const dateStr = now.toISOString().split('T')[0];

const csvRows = [];

// CSV Header
csvRows.push('Name,Geburtsdatum,Wohnadresse,Telefon,Email,Aktuelle Position,Abschlussjahr,Gewünschte Distanz,Zuordnungs-Status,Latitude,Longitude,Zukünftige Arbeitgeber,Distanzen,Kommentar');

// CSV Rows
for (const item of items) {
  const data = item.json;

  const name = (data.property_name || '').replace(/"/g, '""');
  const geburtsdatum = data.property_geburtsdatum || '';
  const adresse = (data.property_wohnadresse || '').replace(/"/g, '""');
  const telefon = data.property_handynummer || '';
  const email = data.property_email || '';
  const position = (data.property_aktuelle_position || '').replace(/"/g, '""');
  const jahr = data.property_abschlussjahr || '';
  const distanz = data.property_gew_nschte_distanz || '';
  const status = data.property_zuordnungs_status || '';
  const lat = data.property_latitude || '';
  const lng = data.property_longitude || '';

  // Zukünftige Arbeitgeber
  const shops = data.property_zuk_nftiger_arbeitgeber || [];
  const shopNames = shops.map(s => s.id).join('; ');

  const distanzen = (data.property_distanz_wohnort_zuk_nftiger_arbeitgeber || '').replace(/"/g, '""').replace(/\n/g, '; ');
  const kommentar = (data.property_kommentar || '').replace(/"/g, '""').replace(/\n/g, '; ');

  csvRows.push(`"${name}","${geburtsdatum}","${adresse}","${telefon}","${email}","${position}","${jahr}","${distanz}","${status}","${lat}","${lng}","${shopNames}","${distanzen}","${kommentar}"`);
}

const csvContent = csvRows.join('\n');

return [{
  json: {
    fileName: `kandidaten-backup-${dateStr}.csv`,
    fileContent: csvContent,
    backupDate: dateStr,
    totalKandidaten: items.length
  },
  binary: {
    data: {
      data: Buffer.from(csvContent, 'utf-8').toString('base64'),
      mimeType: 'text/csv',
      fileName: `kandidaten-backup-${dateStr}.csv`
    }
  }
}];
